import pytest

from bedrock_protocol import v827, v844, v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.PlayerArmourDamage{List: []protocol.PlayerArmourDamageEntry{{ArmourSlot: 1, Damage: 3},
# {ArmourSlot: 4, Damage: -300}}}
TWO_PAIRS = bytes.fromhex("0202030008d4fe")

# generated by gophertunnel b8bd735:
# &packet.PlayerArmourDamage{}
NO_PAIRS = bytes.fromhex("00")

# generated by gophertunnel d6ce91a:
# &packet.PlayerArmourDamage{Bitset: packet.PlayerArmourDamageFlagHelmet | packet.PlayerArmourDamageFlagBoots,
# HelmetDamage: 3, BootsDamage: -2}
HELMET_AND_BOOTS = bytes.fromhex("090603")

# generated by gophertunnel d6ce91a:
# &packet.PlayerArmourDamage{Bitset: 0, HelmetDamage: 99}
EMPTY_MASK = bytes.fromhex("00")

GOLDENS = [
    pytest.param(
        v2225.PlayerArmorDamagePacket(
            slot_and_damage_pairs=[
                v2225.ArmorSlotAndDamagePair(armor_slot=v2225.ArmorSlot.TORSO, damage=3),
                v2225.ArmorSlotAndDamagePair(armor_slot=v2225.ArmorSlot.BODY, damage=-300),
            ]
        ),
        TWO_PAIRS,
        id="v2225-two-pairs",
    ),
    pytest.param(v2225.PlayerArmorDamagePacket(), NO_PAIRS, id="v2225-no-pairs"),
    pytest.param(
        v827.PlayerArmorDamagePacket(slots=0x09, head_damage=3, feet_damage=-2),
        HELMET_AND_BOOTS,
        id="v827-helmet-and-boots",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_player_armor_damage_is_packet_149(version):
    assert version.packets[149] is version.PlayerArmorDamagePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_armor_damage_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_armor_damage_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_player_armor_damage_rejects_a_body_short_of_its_declared_pair_count():
    with pytest.raises(ValueError, match="at byte"):
        v2225.PlayerArmorDamagePacket.from_bytes(TWO_PAIRS[:4])


def test_an_empty_pre_844_slot_mask_is_a_lone_zero_byte():
    assert bytes(v827.PlayerArmorDamagePacket(slots=0, head_damage=99)) == EMPTY_MASK


def test_an_empty_pre_844_slot_mask_decodes_to_no_damage():
    assert v827.PlayerArmorDamagePacket.from_bytes(EMPTY_MASK) == v827.PlayerArmorDamagePacket(slots=0)


def test_player_armor_damage_changes_shape_at_844():
    assert v827.PlayerArmorDamagePacket is not v844.PlayerArmorDamagePacket


def test_player_armor_damage_keeps_its_shape_from_844_to_2168():
    assert v844.PlayerArmorDamagePacket is v2168.PlayerArmorDamagePacket
